.evidence{color:#202c3c;font:15px/1.6 system-ui,sans-serif;max-width:1160px;margin:auto}.print-report{padding:32px}.evidence h1{font-size:32px;line-height:1.2}.evidence h2{font-size:22px}.evidence h3{font-size:17px}.evidence .eyebrow{color:#775318;text-transform:uppercase;letter-spacing:.12em;font-size:12px}.evidence section{background:white;border:1px solid #d8dfe7;border-radius:12px;padding:24px;margin:24px 0}.evidence .tools{display:flex;gap:16px;flex-wrap:wrap;margin:20px 0}.evidence a{color:#205986;text-decoration:underline}.evidence .scroll{overflow:auto}.evidence table{width:100%;border-collapse:collapse;margin:14px 0;font-size:13px}.evidence th{text-align:left;background:#f0f4f8}.evidence td,.evidence th{padding:9px;border:1px solid #d8dfe7;vertical-align:top;overflow-wrap:anywhere}.evidence .status{display:inline-block;background:#fff1d5;color:#694408;border-radius:5px;padding:3px 9px;font-weight:600}.evidence pre{font-size:11px;white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f6f9;padding:14px}.evidence .meta{font-size:12px;color:#4a586a}.evidence details{margin:12px 0}.evidence summary{cursor:pointer;font-weight:600}@media print{.evidence{font-size:10pt}.print-report{padding:0}.evidence section{border:0;padding:0;border-radius:0;page-break-before:auto}.evidence .tools{display:none}.evidence table{font-size:9pt}.evidence tr{break-inside:avoid}.evidence h2{break-after:avoid}.evidence details{display:block}.evidence pre{font-size:8pt}}@media(max-width:600px){.print-report{padding:12px}.evidence section{padding:12px}.evidence h1{font-size:26px}}
.evidence section{overflow-x:auto}.evidence td,.evidence th{overflow-wrap:break-word}.evidence th{min-width:6em}.evidence #audit th:last-child{width:50%}.evidence .status{white-space:nowrap}@media print{.evidence section{overflow:visible}.evidence th{min-width:0}}
